css:
.sl-cta-immersive {
    min-height: clamp(28rem, 72svh, 46rem);
    background-color: #0f172a;
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-cta-immersive .sl-bg-img {
    pointer-events: none;
}
.sl-cta-immersive .sl-immersive-scrim {
    background-color: rgba(15, 23, 42, 0.72);
    pointer-events: none;
}
.sl-cta-immersive .sl-immersive-subtitle {
    color: rgba(255, 255, 255, 0.92);
}
.sl-cta-immersive .sl-cta-btn-label {
    letter-spacing: 0.05em;
}
.sl-cta-immersive .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg) !important;
    border-color: var(--smartlearn-btn-bg) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
}
.sl-cta-immersive .sl-btn-primary:hover,
.sl-cta-immersive .sl-btn-primary:focus-visible {
    transform: translateY(-2px);
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3) !important;
}
.sl-cta-immersive .sl-btn-outline-light {
    transition: transform 0.2s ease;
}
.sl-cta-immersive .sl-btn-outline-light:hover,
.sl-cta-immersive .sl-btn-outline-light:focus-visible {
    transform: translateY(-2px);
}
.sl-cta-immersive a:focus-visible {
    outline: 2px solid #ffffff;
    outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-cta-immersive .sl-btn-primary,
    .sl-cta-immersive .sl-btn-outline-light { transition: none; }
    .sl-cta-immersive .sl-btn-primary:hover,
    .sl-cta-immersive .sl-btn-primary:focus-visible,
    .sl-cta-immersive .sl-btn-outline-light:hover,
    .sl-cta-immersive .sl-btn-outline-light:focus-visible { transform: none; }
}
